The program parses each line with regular expressions and executes the instructions in order. Every line that is not a recognised instruction is skipped, which covers the `// .....` separator lines, the opening instruction sentence and the trailing prompt text.

Three statement forms appear in the input:

- **Constant assignment:** `x <- 47;`
- **Modular add-assign:** `x <- (x + 26) mod 100;`
- **General expression:** `x <- (y + 7) mod 100;`, where `y` can be a different variable from `x`. This form is supported for safety.

```python
import sys
import re

def main():
    text = sys.stdin.read()
    vals = {}
    assign_const = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*(-?\d+)\s*;\s*$')
    assign_expr = re.compile(
        r'^\s*([A-Za-z_]\w*)\s*<-\s*\(\s*([A-Za-z_]\w*|-?\d+)\s*([+\-*])\s*([A-Za-z_]\w*|-?\d+)\s*\)\s*mod\s*(\d+)\s*;\s*$'
    )

    def get(tok):
        if re.fullmatch(r'-?\d+', tok):
            return int(tok)
        return vals.get(tok, 0)

    for line in text.splitlines():
        s = line.strip()
        if not s or s.startswith('//'):
            continue
        m = assign_const.match(s)
        if m:
            vals[m.group(1)] = int(m.group(2))
            continue
        m = assign_expr.match(s)
        if m:
            var, x, op, y, md = m.groups()
            a = get(x)
            b = get(y)
            md = int(md)
            if op == '+':
                r = a + b
            elif op == '-':
                r = a - b
            else:
                r = a * b
            vals[var] = r % md
            continue
        # ignore anything else (e.g., instruction text)

    order = list("abcdefghijklmnop") + ["TMP"]
    out = " ".join("%s ?= %d;" % (v, vals.get(v, 0)) for v in order)
    print(out)

if __name__ == "__main__":
    main()
